code.source:
#include <iostream>
using namespace std;

int main() {
    for (int i = 1; i <= 5; i++) {
        cout << "Round " << i << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    for (int i = 1; i <= 5; i++) {
        cout << "7 x " << i << " = " << 7 * i << endl;
    }
    for (int k = 3; k >= 1; k--) {
        cout << k << " ";
    }
    cout << endl;
    return 0;
}

